// src/lib/plattform/backend/index.js
//
// Einheitliche Backend-Schnittstelle der Plattform. Zwei Implementierungen:
//   frappe.js – Frappe-App `oekoinvest_app` (Produktion), Auswahl mit PLATTFORM_BACKEND=frappe
//   demo.js   – JSON-Datei unter .data/plattform.json (Entwicklung/Vorführung)
//
// Im Produktions-Build wird das Demo-Backend NUR genutzt, wenn PLATTFORM_DEMO=1 gesetzt ist –
// sonst gibt es eine klare Fehlermeldung (HTTP 503) statt stiller Demo-Daten.
//
// Nur serverseitig verwenden (Route-Handler, Server-Komponenten).
//
// Alle Operationen (Signaturen identisch in beiden Implementierungen; n = angemeldeter Nutzer):
//   Konto:     anmelden({email,passwort}) · nutzerFuerSitzung(id) · registrieren({...}) · emailBestaetigen({token})
//              passwortVergessen({email,basisUrl,ip}) · passwortSetzen({token,passwort,ip}) · passwortAendern(n,{alt,neu})
//              profilSpeichern(n,daten) · suchprofilSpeichern(n,profil)
//   Anfrage:   anfrageAnlegen({typ,kontakt,daten,herkunft,ip,einwilligungText,nutzer})
//   Vorgänge:  vorgaenge(n,{alle,status,typ,q}) · vorgang(n,id)
//   Flächen:   flaechen(n,{alle,status}) · flaeche(n,id) · flaecheAnlegen(n,daten,{ip}) · flaecheAendern(n,id,daten)
//   Projekte:  projekte(n,{alle,status}) · projekt(n,id) · projektAnlegen(n,daten,{ip}) · projektAendern(n,id,daten)
//              provisionAkzeptieren(n,id,{ip})
//   Börse:     boerse(n|null,filter) · boerseDetail(n|null,slugOderId,{zaehlen})
//   Interesse: merken(n,projektId,an) · ndaAnfragen(n,projektId,{akzeptiert,ip,userAgent}) · interessen(n,{alle,status,projektId})
//   Prozess:   statusWechsel(n,{art,id,nach,als,extra,ip})
//   Nachricht: nachrichtenThreads(n) · nachrichten(n,bezugArt,bezugId,{markieren}) · nachrichtSenden(n,{bezugArt,bezugId,text})
//   Dokument:  dokumente(n,{bezugArt,bezugId}) · dokumentLesen(n,id) · dokumentSpeichern(n,{...,daten}) · dokumentLoeschen(n,id)
//   Admin:     zuweisen · nutzerListe · nutzerAendern · provisionen · aktivitaeten · adminKonten · adminUebersicht · demoLinks
//   Hinweise:  benachrichtigungen(n,{nurUngelesen,limit}) · benachrichtigungenGelesen(n,{ids,alle}) · mailEinstellungenSpeichern(n,einstellungen)
//   Aufgaben:  aufgaben(n,{zustaendigId,status,bezugArt,bezugId,nurUeberfaellig}) · aufgabeAnlegen(n,daten) · aufgabeAendern(n,id,daten)
//   Exposé:    exposeDaten(n,id,{ip}) (Rechte + Protokoll, PDF erzeugt die Website) · protokollEintrag(n,{aktion,objektArt,objektId,text,ip})
//   Nur Demo:  postausgang(n,{limit}) (E-Mails, die Frappe versenden würde; im Frappe-Adapter [])

import * as demo from "./demo";
import * as frappe from "./frappe";
import { PlattformFehler } from "../fehler";

export const OPERATIONEN = [
  "anmelden", "nutzerFuerSitzung", "registrieren", "emailBestaetigen", "passwortVergessen", "passwortSetzen", "passwortAendern",
  "profilSpeichern", "suchprofilSpeichern", "anfrageAnlegen", "vorgaenge", "vorgang", "flaechen", "flaeche", "flaecheAnlegen",
  "flaecheAendern", "projekte", "projekt", "projektAnlegen", "projektAendern", "provisionAkzeptieren", "boerse", "boerseDetail",
  "merken", "ndaAnfragen", "interessen", "statusWechsel", "nachrichtenThreads", "nachrichten", "nachrichtSenden", "dokumente",
  "dokumentLesen", "dokumentSpeichern", "dokumentLoeschen", "zuweisen", "nutzerListe", "nutzerAendern", "provisionen",
  "aktivitaeten", "adminKonten", "adminUebersicht", "demoLinks", "benachrichtigungen", "benachrichtigungenGelesen",
  "mailEinstellungenSpeichern", "postausgang", "aufgaben", "aufgabeAnlegen", "aufgabeAendern", "exposeDaten", "protokollEintrag",
];

if (process.env.NODE_ENV !== "production") {
  for (const [name, impl] of [["demo", demo], ["frappe", frappe]]) {
    const fehlt = OPERATIONEN.filter((op) => typeof impl[op] !== "function");
    if (fehlt.length) console.warn(`[plattform] Backend ${name}: fehlende Operationen ${fehlt.join(", ")}`);
  }
}

export const KONFIG_FEHLER =
  "Das Plattform-Backend ist nicht konfiguriert. Für den Betrieb PLATTFORM_BACKEND=frappe setzen (siehe docs/PLATTFORM.md) – oder PLATTFORM_DEMO=1 für eine reine Vorführung.";

export function backendName() {
  if (process.env.PLATTFORM_BACKEND === "frappe") return "frappe";
  if (process.env.NODE_ENV === "production" && process.env.PLATTFORM_DEMO !== "1") return null;
  return "demo";
}

/** Liefert die aktive Implementierung oder wirft 503 */
export function backend() {
  const n = backendName();
  if (n === "frappe") return frappe;
  if (n === "demo") return demo;
  throw new PlattformFehler(503, KONFIG_FEHLER);
}

export const istDemo = () => backendName() === "demo";
// src/lib/plattform/backend/frappe.js
//
// Frappe-Backend: spricht die Frappe-App `oekoinvest_app` über whitelisted Methoden an.
// Vertrag (Methoden, Felder, Rechte, Fehler): docs/API.md.
//
//  - Server-zu-Server mit API-Key/Secret (SERVER, API_KEY, API_SECRET wie src/lib/apiBaseUrl.js).
//    Der API-Nutzer hat in Frappe nur die Rolle „ÖkoInvest API“.
//  - Aktionen im Namen des eingeloggten Nutzers: jedes Argument-Objekt enthält `als_benutzer`
//    (Konto-ID `nutzer.id`, z. B. U-26-7KQ2XM). Die Frappe-App löst daraus den Frappe-User auf,
//    wechselt per frappe.set_user() in den Nutzer und prüft Rolle UND Eigentum selbst –
//    die Next.js-Seite ist nur die erste Verteidigungslinie.
//  - Argumente und Antworten in camelCase-JSON, identisch zum Demo-Backend.
//  - Liefert eine Methode `None` (z. B. anmelden mit falschen Daten), fehlt `message` in der
//    Frappe-Antwort – der Adapter gibt dann `null` zurück (wie das Demo-Backend).

import { API_BASE_URL, getApiHeaders, isApiConfigured } from "@/lib/apiBaseUrl";
import { PlattformFehler } from "../fehler";

export const name = "frappe";

const PRAEFIX = "oekoinvest_app.plattform.api.";
const TIMEOUT_MS = 15000;

/** Methodenname je Operation – muss mit docs/API.md übereinstimmen */
export const METHODEN = {
  anmelden: "auth.anmelden",
  nutzerFuerSitzung: "auth.nutzer_fuer_sitzung",
  registrieren: "auth.registrieren",
  emailBestaetigen: "auth.email_bestaetigen",
  passwortVergessen: "auth.passwort_vergessen",
  passwortSetzen: "auth.passwort_setzen",
  passwortAendern: "konto.passwort_aendern",
  profilSpeichern: "konto.profil_speichern",
  suchprofilSpeichern: "konto.suchprofil_speichern",
  anfrageAnlegen: "anfrage.anlegen",
  vorgaenge: "vorgang.liste",
  vorgang: "vorgang.holen",
  flaechen: "flaeche.liste",
  flaeche: "flaeche.holen",
  flaecheAnlegen: "flaeche.anlegen",
  flaecheAendern: "flaeche.aendern",
  projekte: "projekt.liste",
  projekt: "projekt.holen",
  projektAnlegen: "projekt.anlegen",
  projektAendern: "projekt.aendern",
  provisionAkzeptieren: "projekt.provision_akzeptieren",
  boerse: "boerse.liste",
  boerseDetail: "boerse.detail",
  merken: "interesse.merken",
  ndaAnfragen: "interesse.nda_anfragen",
  interessen: "interesse.liste",
  statusWechsel: "prozess.status_wechsel",
  nachrichtenThreads: "nachricht.threads",
  nachrichten: "nachricht.liste",
  nachrichtSenden: "nachricht.senden",
  dokumente: "dokument.liste",
  dokumentLesen: "dokument.lesen",
  dokumentSpeichern: "dokument.speichern",
  dokumentLoeschen: "dokument.loeschen",
  zuweisen: "admin.zuweisen",
  nutzerListe: "admin.nutzer_liste",
  nutzerAendern: "admin.nutzer_aendern",
  provisionen: "admin.provisionen",
  aktivitaeten: "admin.aktivitaeten",
  adminKonten: "admin.admin_konten",
  adminUebersicht: "admin.uebersicht",
  protokollEintrag: "admin.protokoll_eintrag",
  benachrichtigungen: "benachrichtigung.liste",
  benachrichtigungenGelesen: "benachrichtigung.gelesen",
  mailEinstellungenSpeichern: "benachrichtigung.einstellungen_speichern",
  aufgaben: "aufgabe.liste",
  aufgabeAnlegen: "aufgabe.anlegen",
  aufgabeAendern: "aufgabe.aendern",
  exposeDaten: "boerse.expose",
};

function meldung(daten) {
  let text = "";
  try {
    const liste = JSON.parse(daten?._server_messages || "[]");
    text = JSON.parse(liste[0] || "{}").message || "";
  } catch {
    /* keine Servermeldung */
  }
  if (!text && typeof daten?.exception === "string") text = daten.exception.replace(/^[\w.]*(Error|Exception):\s*/, "");
  return text.replace(/<[^>]*>/g, "").replace(/\s+/g, " ").trim().slice(0, 240);
}

async function aufruf(op, args = {}, nutzer = null) {
  if (!isApiConfigured() || !process.env.SERVER) {
    throw new PlattformFehler(503, "Das Plattform-Backend (Frappe) ist nicht konfiguriert.");
  }
  const url = `${API_BASE_URL}${PRAEFIX}${METHODEN[op]}`;
  let res;
  try {
    res = await fetch(url, {
      method: "POST",
      headers: getApiHeaders(),
      body: JSON.stringify({ ...args, ...(nutzer ? { als_benutzer: nutzer.id } : {}) }),
      cache: "no-store",
      signal: AbortSignal.timeout(TIMEOUT_MS),
    });
  } catch (e) {
    console.error(`[plattform-frappe] ${op}: nicht erreichbar`, e?.message);
    throw new PlattformFehler(502, "Der Server ist vorübergehend nicht erreichbar.");
  }
  if (res.ok) {
    const j = await res.json().catch(() => ({}));
    return j.message ?? null;
  }
  const roh = await res.text().catch(() => "");
  let daten = {};
  try {
    daten = JSON.parse(roh);
  } catch {
    daten = {};
  }
  // Interna (Traceback) nur ins Server-Log – nie an den Browser
  console.error(`[plattform-frappe] ${op}: HTTP ${res.status} ${daten.exc_type || ""}`);
  const text = meldung(daten);
  const typ = String(daten.exc_type || "");
  if (res.status === 401 || /AuthenticationError/.test(typ)) throw new PlattformFehler(401, "Bitte melden Sie sich an.");
  if (res.status === 403 || /PermissionError/.test(typ)) throw new PlattformFehler(403, text || "Dafür fehlt Ihnen die Berechtigung.");
  if (res.status === 404 || /DoesNotExistError/.test(typ)) throw new PlattformFehler(404, text || "Nicht gefunden.");
  if (res.status === 409 || /DuplicateEntryError|TimestampMismatchError/.test(typ)) throw new PlattformFehler(409, text || "Konflikt – bitte neu laden.");
  if (res.status === 429) throw new PlattformFehler(429, "Zu viele Anfragen – bitte warten Sie einen Moment.");
  if (/ValidationError|MandatoryError|LinkValidationError/.test(typ) || res.status === 417) throw new PlattformFehler(422, text || "Eingabe ungültig.");
  throw new PlattformFehler(502, "Der Server ist vorübergehend nicht erreichbar.");
}

// ---------------------------------------------------------------- Konto
