238	/** Freie Zusatzdaten einer Anfrage bereinigen (flach, begrenzt) */
239	function datenBereinigen(d, tiefe = 0) {
240	  if (!d || typeof d !== "object" || Array.isArray(d)) return {};
241	  const out = {};
242	  for (const [k, wert] of Object.entries(d).slice(0, 60)) {
243	    const key = String(k).replace(/[^\w.-]/g, "").slice(0, 60);
244	    if (!key || key === "__proto__" || key === "constructor" || key === "prototype") continue;
245	    if (typeof wert === "string") out[key] = v.mehrzeilig(wert, 2000);
246	    else if (typeof wert === "number" && Number.isFinite(wert)) out[key] = wert;
247	    else if (typeof wert === "boolean") out[key] = wert;
248	    else if (Array.isArray(wert)) out[key] = wert.slice(0, 30).map((x) => (typeof x === "number" || typeof x === "boolean" ? x : v.text(x, 200)));
249	    else if (wert && typeof wert === "object" && tiefe < 1) out[key] = datenBereinigen(wert, tiefe + 1);
250	  }
251	  return out;
252	}
