      const standard = r.nutzer?.rollen?.includes("admin") ? "/portal/admin" : "/portal";
      router.replace(sicheresZiel(weiter, standard));
      router.refresh();
    } catch (err) {
      setFehler(err.message);
      setLaeuft(false);
