 * (+ zweiFaktorMethode, codesUebrig) oder wirft 401 (code „zwei_faktor“) bzw. 429 (gesperrt).
 */
export async function zweiFaktorPruefen({ nutzerId, code, ip = "", userAgent = "", land = "" } = {}) {
  return aendern((db) => {
