    });
    _intern.verknuepfen(db, u);
    _intern.protokoll(db, u, "email_aendern", "nutzer", u.id, `Anmeldeadresse geändert: ${alt} → ${neu}`);
    return _intern.ohneGeheimnis(u);
  });
}

