  if (!n) throw new PlattformFehler(401, "Bitte melden Sie sich an.");
  const db = await lesen();
  let liste = db.dokumente;
  if (bezugArt) liste = liste.filter((d) => d.bezugArt === bezugArt && d.bezugId === bezugId);
