export async function tokenErstellen({ nutzerId, version = 0 }) {
  const jetzt = Math.floor(Date.now() / 1000);
  const payload = b64u(enc.encode(JSON.stringify({ u: nutzerId, v: version, iat: jetzt, exp: jetzt + SITZUNG_DAUER_S })));
