// Prüft benannte Importe (relative/@-Pfade) in den übergebenen Dateien gegen die Exporte der Zieldateien
const fs = require("fs"), path = require("path");
const ROOT = process.argv[2];
function aufloesen(von, spec) {
  let p = spec.startsWith("@/") ? path.join(ROOT, "src", spec.slice(2)) : path.resolve(path.dirname(von), spec);
  for (const k of [p, p + ".js", path.join(p, "index.js")]) if (fs.existsSync(k) && fs.statSync(k).isFile()) return k;
  return null;
}
function exporte(f, tiefe = 0) {
  const s = fs.readFileSync(f, "utf8"); const out = new Set();
