      <span>{children}</span>
      {pfeil && (
        <ArrowRight
          aria-hidden="true"
          className="h-[1.05em] w-[1.05em] shrink-0 transition-transform duration-300 group-hover:translate-x-1"
        />
      )}
    </>
  );

  if (href) {
    const extern = /^(https?:|tel:|mailto:)/.test(href);
