}

/** Statusverlauf als Timeline */
export function Timeline({ art, verlauf = [], leerText = "Noch keine Einträge." }) {
  if (!verlauf.length) return <p className="text-[14px] text-ink-500">{leerText}</p>;
  const liste = [...verlauf].reverse();
