10	import { phaseById } from "@/lib/invest/markt";
11	
12	export const metadata = { title: "Profil" };
13	
14	export default async function Profil() {
15	  const n = await portalNutzer();
16	  const investor = hatRolle(n, "investor") && n.rollen.includes("investor");
17	  const boerse = investor ? await backend().boerse(n, {}) : null;
18	  const passende = boerse ? boerse.projekte.filter((p) => p.matching).sort((a, b) => b.matching.score - a.matching.score).slice(0, 6) : [];
19	
20	  return (
21	    <div className="space-y-6">
22	      <SeitenKopf eyebrow="Konto" titel={investor ? "Profil & Suchprofil" : "Profil"} text="Ihre Stammdaten, Rollen und Sicherheit." />
23	      {n.emailBestaetigt ? (
