// Visuelle Kontrolle „Login, Sicherheit & Teams“: node sec_shots.mjs <breite> [nur=szenario,..]
import { chromium } from "playwright";
import { createHmac } from "node:crypto";
import { fileURLToPath } from "node:url";

const B = "http://localhost:3100";
const breite = Number(process.argv[2] || 1440);
const nur = (process.argv[3] || "").split(",").filter(Boolean);
const LAUF = Date.now().toString(36);
const PW = `Sicher-${LAUF}-Passwort1`;

const B32 = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
const b32 = (s) => { let bits = 0, w = 0; const o = []; for (const z of s) { w = (w << 5) | B32.indexOf(z); bits += 5; if (bits >= 8) { o.push((w >>> (bits - 8)) & 255); bits -= 8; } } return Buffer.from(o); };
const totp = (g, d = 0) => { const b = Buffer.alloc(8); b.writeBigUInt64BE(BigInt(Math.floor(Date.now() / 30000) + d)); const h = createHmac("sha1", b32(g)).update(b).digest(); const o = h[19] & 15; return String((((h[o] & 127) << 24) | (h[o + 1] << 16) | (h[o + 2] << 8) | h[o + 3]) % 1e6).padStart(6, "0"); };

async function api(cookie, method, pfad, body) {
  const r = await fetch(B + pfad, { method, headers: { Origin: B, "Content-Type": "application/json", ...(cookie.v ? { Cookie: cookie.v } : {}) }, body: body ? JSON.stringify(body) : undefined, redirect: "manual" });
  const set = r.headers.getSetCookie?.() || [];
  const map = new Map((cookie.v || "").split("; ").filter(Boolean).map((x) => [x.split("=")[0], x.slice(x.indexOf("=") + 1)]));
  for (const c of set) { const p = c.split(";")[0]; const n = p.slice(0, p.indexOf("=")); const v = p.slice(p.indexOf("=") + 1); if (v) map.set(n, v); else map.delete(n); }
  cookie.v = [...map].map(([k, v]) => `${k}=${v}`).join("; ");
  return r.json().catch(() => ({}));
}

const browser = await chromium.launch();
async function shot(name, pfad, { cookie, aktion, voll = true } = {}) {
  if (nur.length && !nur.includes(name)) return;
  const ctx = await browser.newContext({ viewport: { width: breite, height: breite < 600 ? 844 : 900 } });
  if (cookie?.v) await ctx.addCookies(cookie.v.split("; ").map((x) => ({ name: x.split("=")[0], value: x.slice(x.indexOf("=") + 1), domain: "localhost", path: "/" })));
  const p = await ctx.newPage();
  const fehler = [];
  p.on("pageerror", (e) => fehler.push("PAGEERROR " + e.message));
  p.on("console", (m) => m.type() === "error" && fehler.push("CONSOLE " + m.text().slice(0, 200)));
  const r = await p.goto(B + pfad, { waitUntil: "networkidle", timeout: 180000 });
  try { await p.getByRole("button", { name: "Nur notwendige" }).click({ timeout: 1500 }); } catch {}
  if (aktion) await aktion(p);
  await p.waitForTimeout(800);
  const ueber = await p.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
  await p.screenshot({ path: fileURLToPath(new URL(`./shots/sec_${name}_${breite}.png`, import.meta.url)), fullPage: voll });
  console.log(r.status(), name, ueber > 0 ? `ÜBERLAUF ${ueber}px` : "", fehler.join(" | "));
  await ctx.close();
}

// Testkonto mit 2FA (aktiv) + Organisation
const k = { v: "" };
const email = `sec-shot-${LAUF}@example.com`;
await api(k, "POST", "/api/auth/registrieren", { email, passwort: PW, vorname: "Jana", nachname: "Beispiel (Demo)", rollen: ["anbieter", "investor"], agb: true });
const e = await api(k, "POST", "/api/portal/sicherheit/zwei-faktor", { aktion: "starten" });
await api(k, "POST", "/api/portal/sicherheit/zwei-faktor", { aktion: "bestaetigen", code: totp(e.geheimnis) });
const org = await api(k, "POST", "/api/portal/organisation", { name: "Beispiel Solar GmbH (fiktiv)", art: "projektentwickler" });
await api(k, "POST", "/api/portal/projekte", { titel: "Solarpark Beispiel (Demo)", typ: "freiflaeche", land: "DE", mwp: 8 });
await api(k, "POST", `/api/portal/organisation/${org.organisation?.id}/einladungen`, { email: `sec-shot-kollegin-${LAUF}@example.com`, rolle: "mitglied" });
const admin = { v: "" };
await api(admin, "POST", "/api/auth/login", { email: "admin@example.com", passwort: "Demo-2026!" });
const links = await api(admin, "GET", "/api/admin/demo-links");
const einl = links.links?.find((l) => l.art === "einladung" && l.email === `sec-shot-kollegin-${LAUF}@example.com`)?.link;
// Konto ohne 2FA (Einrichtung zeigen)
const k2 = { v: "" };
await api(k2, "POST", "/api/auth/registrieren", { email: `sec-shot2-${LAUF}@example.com`, passwort: PW, vorname: "Tom", nachname: "Muster (Demo)", rollen: ["flaeche"], agb: true });

await shot("login", "/login");
await shot("login_link_tab", "/login", { aktion: (p) => p.getByRole("tab", { name: /E-Mail-Link/ }).click() });
await shot("login_2fa", "/login", {
  aktion: async (p) => {
    await p.getByLabel("E-Mail-Adresse").first().fill(email);
    await p.getByLabel("Passwort", { exact: true }).fill(PW);
    await p.getByRole("button", { name: "Anmelden", exact: true }).click();
    await p.getByText("Code aus der App").waitFor({ timeout: 60000 });
  },
});
await shot("login_link", "/login/link?token=abcdefghijklmnopqrstuvwxyz0123456789ABCDEFG");
await shot("sicherheit", "/portal/sicherheit", { cookie: k });
await shot("sicherheit_einrichten", "/portal/sicherheit", { cookie: k2, aktion: async (p) => { await p.getByRole("button", { name: "Zwei-Faktor einrichten" }).click(); await p.getByText("Code aus der App").waitFor({ timeout: 60000 }); } });
await shot("organisation", "/portal/organisation", { cookie: k });
await shot("organisation_leer", "/portal/organisation", { cookie: k2 });
await shot("org_menue", "/portal", { cookie: k, voll: false, aktion: async (p) => { await p.getByRole("button", { name: /Organisation wechseln/ }).click(); } });
if (einl) await shot("einladung", new URL(einl).pathname);
await shot("profil", "/portal/profil", { cookie: k2 });
await browser.close();

